    var var_skills = sse_decode_list_skill(deserializer);
    return SkillChain(
      id: var_id,
      name: var_name,
      isActivePrivate: var_isActivePrivate,
      isActivePublic: var_isActivePublic,
      skills: var_skills,
    );
  }

  @protected
  TensionZone sse_decode_tension_zone(SseDeserializer deserializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    var inner = sse_decode_i_32(deserializer);
    return TensionZone.values[inner];
  }

